import{_ as e,o,c as r,ai as a}from"./chunks/framework.CUYGB37K.js";const h=JSON.parse('{"title":"Configurable Product","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/products/configurable.md","filePath":"2.0/products/configurable.md","lastUpdated":1776149834000}'),s={name:"2.0/products/configurable.md"};function i(n,t,l,c,u,d){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="configurable-product" tabindex="-1">Configurable Product <a class="header-anchor" href="#configurable-product" aria-label="Permalink to &quot;Configurable Product&quot;">​</a></h1><p>It refers to a type of product that offers various options or variations, such as size, color, or features, which can be selected by the customer. The PIM system manages these options and their associated attributes, ensuring accurate and comprehensive product information across different configurations.</p><p>Configurable products are designed to meet individual needs, enhancing customer satisfaction and providing a tailored experience in <a href="https://unopim.com/" target="_blank" rel="noreferrer">UnoPim</a>.</p><h3 id="create-configurable-product-in-unopim" tabindex="-1">Create Configurable Product in UnoPim <a class="header-anchor" href="#create-configurable-product-in-unopim" aria-label="Permalink to &quot;Create Configurable Product in UnoPim&quot;">​</a></h3><ol><li>Click on <strong>Catalog &gt;&gt; Products &gt;&gt;</strong> select <strong>Configurable</strong> , <strong>Family</strong> and enter <strong>SKU</strong> under Product Type .</li></ol><p>Now click on <strong>Save the Product</strong>, and now select the <strong>configurable attributes</strong> as per your requirements, and then click on <strong>Save Product</strong> button.</p><h3 id="configurable-super-attributes" tabindex="-1">Configurable (Super) Attributes <a class="header-anchor" href="#configurable-super-attributes" aria-label="Permalink to &quot;Configurable (Super) Attributes&quot;">​</a></h3><p>When creating a configurable product, you need to select <strong>super attributes</strong> — these are the attributes that define the variations of your product (e.g., Size, Color).</p><p>In UnoPim v2.0, configurable product super attributes are fully supported with:</p><ul><li>Flexible super attribute selection during product creation</li><li>Support for <strong>variants_json</strong> format for programmatic variant definition</li><li>Size-based variants with configurable seeder support</li></ul><h3 id="general-attributes" tabindex="-1">General Attributes <a class="header-anchor" href="#general-attributes" aria-label="Permalink to &quot;General Attributes&quot;">​</a></h3><p>It displays the attributes assigned in the product&#39;s family grouped by attribute group.</p><p>The below given are required attributes present in the &quot;default&quot; family</p><ol><li><p>Enter <strong>SKU</strong> of the product</p></li><li><p>Enter <strong>Name</strong> of the product</p></li><li><p>Now enter the <strong>URL Key</strong> of the product</p></li></ol><h3 id="short-description" tabindex="-1">Short Description <a class="header-anchor" href="#short-description" aria-label="Permalink to &quot;Short Description&quot;">​</a></h3><p>Enter a short description of the features of the product.</p><h3 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h3><p>Mention your product in detail.</p><h3 id="technical" tabindex="-1">Technical <a class="header-anchor" href="#technical" aria-label="Permalink to &quot;Technical&quot;">​</a></h3><p>Now Enable the product from the status option as shown below.</p><h3 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h3><p>You can also assign the product into the root category as shown in the below image.</p><h3 id="variations" tabindex="-1">Variations <a class="header-anchor" href="#variations" aria-label="Permalink to &quot;Variations&quot;">​</a></h3><p>Now enter the variations of the product. Click on <strong>Add Product</strong> to add a new variant.</p><p>Now add the variant — enter the configurable attributes and then click on <strong>Add button</strong>.</p><p>You can add as many variants as per the requirements of the product.</p><h3 id="associations" tabindex="-1">Associations <a class="header-anchor" href="#associations" aria-label="Permalink to &quot;Associations&quot;">​</a></h3><p>Also, you can add the Related Products, Upsell Products, and Cross-Sell Products.</p><p><strong>1) Related Products -</strong> Related products are products that are similar to a selected product. You can display potential substitutes help to them discover other similar products they might like.</p><p>To add Related Products click on Add in the Related Products section and search the product through the SKU which you want to add as a Related Product.</p><p>Now click on <strong>Add Selected Product</strong> button.</p><p><strong>2) Up-Sell Products -</strong> Upselling is the practice of selling a higher-end version of an item they&#39;re interested in.</p><p>For instance, an electronics retailer pointing out the benefits of a better TV, a faster laptop, or a more durable tablet would be an example of upselling.</p><p>To add Up-Sell Products click on add in the Up-Sell Products section and search the product through the SKU which you want to add as a Up-Sell Product.</p><p>Now click on <strong>Add Selected Product</strong> button.</p><p><strong>3) Cross-Sell Products -</strong> Cross-sells are products that you promote, based on the current product. They are typically complementary items. For example, if you are selling a laptop, cross-sells might be protective case stickers or a special adapter.</p><p>To add Cross-Sell Products click on add in the Cross-Sell Products section and search the product through SKU which you want to add as a Cross-Sell Product.</p><p>Now click on <strong>Add Selected Product</strong> button.</p><p>You can also add as many products as per your requirements.</p><p>At last, <strong>Save the Product</strong>.</p><p>Now the product has been created successfully and will be visible in the Products Data Grid.</p><h2 id="product-completeness" tabindex="-1">Product Completeness <a class="header-anchor" href="#product-completeness" aria-label="Permalink to &quot;Product Completeness&quot;">​</a></h2><p>Configurable products also benefit from the <strong>Product Completeness</strong> system. The completeness score evaluates both the parent product and its variants, providing a holistic quality score.</p><ul><li>Completeness is calculated per channel and per locale</li><li>The dashboard shows completeness percentages for each channel</li><li>Low-completeness products are flagged for attention</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Focus on completing the parent product attributes first, then ensure each variant has its required attribute values filled in.</p></div><h2 id="product-bulk-edit" tabindex="-1">Product Bulk Edit <a class="header-anchor" href="#product-bulk-edit" aria-label="Permalink to &quot;Product Bulk Edit&quot;">​</a></h2><p>You can use <strong>Bulk Edit</strong> to update multiple configurable products at once. Select products from the datagrid and apply bulk changes to shared attributes.</p><h2 id="product-history" tabindex="-1">Product History <a class="header-anchor" href="#product-history" aria-label="Permalink to &quot;Product History&quot;">​</a></h2><p>You can view the product history by navigating to <strong>Catalog &gt;&gt; Products &gt;&gt; Edit Product</strong> and clicking on <strong>History</strong>.</p><h2 id="quick-export" tabindex="-1">Quick Export <a class="header-anchor" href="#quick-export" aria-label="Permalink to &quot;Quick Export&quot;">​</a></h2><p>You can quickly export your data into <strong>CSV, XLS, XLSX</strong> format directly from the product listing.</p><p><strong>Note:</strong> Attributes that support values per channel will display a channel badge, while attributes that support values per locale will display a locale badge. If an attribute supports both values per channel and values per locale, it will display both badges.</p>',52)])])}const g=e(s,[["render",i]]);export{h as __pageData,g as default};
